+@page "/board"
+@rendermode InteractiveServer
+@inject ITaskService TaskService
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h3 class="mb-3">Kanban Board</h3>
+
+@if (loading)
+{
+    <div class="text-center my-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading...</span>
+        </div>
+    </div>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger">
+        <strong>Error:</strong> @errorMessage
+        <button class="btn btn-link" @onclick="LoadTasks">Retry</button>
+    </div>
+}
+else
+{
+    <BoardSummaryBar Total="allTasks.Count"
+                     ToDo="GetTasksForStatus(StatusToDo).Count"
+                     InProgress="GetTasksForStatus(StatusInProgress).Count"
+                     Done="GetTasksForStatus(StatusDone).Count"
+                     Overdue="allTasks.Count(t => t.DueDate < DateTime.Today)" />
+
+    <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />
+
+    <div class="row g-3">
+        <KanbanColumn Title="To Do"
+                      Status="@StatusToDo"
+                      Tasks="GetFilteredTasksForStatus(StatusToDo)"
+                      ShowMoveLeft="false"
+                      ShowMoveRight="true"
+                      RightStatus="@StatusInProgress"
+                      OnMoveTask="HandleMoveTask"
+                      OnTaskCreated="HandleTaskCreated" />
+
+        <KanbanColumn Title="In Progress"
+                      Status="@StatusInProgress"
+                      Tasks="GetFilteredTasksForStatus(StatusInProgress)"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="true"
+                      LeftStatus="@StatusToDo"
+                      RightStatus="@StatusDone"
+                      OnMoveTask="HandleMoveTask"
+                      OnTaskCreated="HandleTaskCreated" />
+
+        <KanbanColumn Title="Done"
+                      Status="@StatusDone"
+                      Tasks="GetFilteredTasksForStatus(StatusDone)"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="false"
+                      LeftStatus="@StatusInProgress"
+                      OnMoveTask="HandleMoveTask"
+                      OnTaskCreated="HandleTaskCreated" />
+    </div>
+}
+
+@code {
+    private const string StatusToDo = "To Do";
+    private const string StatusInProgress = "In Progress";
+    private const string StatusDone = "Done";
+
+    private List<TaskItem> allTasks = new();
+    private string searchText = "";
+    private bool loading = true;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        loading = true;
+        errorMessage = null;
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            loading = false;
+        }
+    }
+
+    private List<TaskItem> GetTasksForStatus(string status) =>
+        allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredTasksForStatus(string status) =>
+        allTasks
+            .Where(t => t.Status == status)
+            .Where(t => string.IsNullOrEmpty(searchText)
+                || t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
+            .ToList();
+
+    private void OnSearchChanged(string value)
+    {
+        searchText = value;
+    }
+
+    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
+            var task = allTasks.First(t => t.Id == move.TaskId);
+            var index = allTasks.IndexOf(task);
+            allTasks[index] = task with { Status = move.NewStatus };
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async Task HandleTaskCreated(TaskItem formData)
+    {
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(
+                formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
+            allTasks.Add(created);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
+

